INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1487820-mis311', 'stk-h-a-g', 'MIS 311', 'info', '{"desc": "جودة المقرر بشكل عام\nالكورس يعتبر بالنسبة لي اهم كورس في الـMIS واكثرهم فائدة. الكورس فيه كلاسين اسبوعيا ولاب واحد مدته ساعتين. الكورس يتكلم عن قواعد البيانات Relational Database ، نفس المبدأ حق الأكسس وراح تبني الDB بلغة الـSQL المتخصصة في جداول البيانات. الكورس يتكلم عن الاشياء اللي ما تنشاف في قاعدة البيانات يعني الاشياء اللي ماهي ظاهرة للمستخدم (ما يتطرق ابدا لواجهة المستخدم) والكورس يكون فيه بروجكت مطلوب منك انك مع الفريق حقك تبنون قاعدة بيانات لاي شركة تختارونها بشرط تكون الداتا بيس حقيقية مو تأليف (يعني لازم تزورون الشركة اكثر من مرة عشان تأخذون البيانات منهم)\n\nالكورس كله عن الـ Implementation Phase اللي اخذناها في MIS301\n\n**المواضيع التي يغطيها المقرر **\nاللي اتذكره انه يتكلم عن Entity Relationship Diagrams (ERD) ويعلمك لغة SQL واللي هي تعتبر من اسهل لغات البرمجة ومتخصصة في بناء قواعد البيانات.\n\nالكتاب المستخدم للمقرر\nالكتاب فيه امثلة واسئلة نهاية الشابتر كثيرة ومفيدة جدا. يعني لو بعد ما تخلص كل شابتر تحل وتفهم اسئلة النهاية بتعدي الكورس بـA+ وأنت محترف SQL\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمفيدة ومهمة جدا\n\nمدى فائدته في الناحية التطبيقية\nمن أهم الكورسات من ناحية الفائدة خصوصا لو أنت بتشتغل Technical سواء في الكواب ولا الوظيفة في المستقبل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-311-business-data-management/120976/3", "user": "H-A-G", "ts": 1518611268000, "tid": 120976, "pn": 3}}', 1518611268000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-mis311', 'stk-s.a.l.m.a.n', 'MIS 311', 'doc', '{"docs": [{"id": "stk-dr-f98435", "n": "Dr. Mohammad Saad Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده mis311\n\nالتحضير :\n\nبداية كل كلاس , و يهتم بالتحضير , اللي ما عنده ولا غياب يعطيه درجتين بونص , واللي عنده غياب واحد يعطيه درجه\n\nطريقة الشرح :\nيشرح من السلايدات , ومتفاني في الشرح , ويتطرق احيانا لتطبيقات المفاهيم بحكم ان الكورس تيكنيكال\n\nالكويزات :\nسهله الى متوسطه\n\nالمياجر:\nسهله الى متوسطه , عباره عن اختيارات و جزء مسائل\nطويله نوعا ما , يجيب اسئلة بونص في ميجر 2 والفاينل\nالفاينلات :\nنفس المياجر\n\nالقريد النهائي:\nاعطي الدكتور +a\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور حبيب جدا ومحترم , ومخلص في شرحه , اهم شي عنده ان الطالب يفهم الكونسيبت , راح يمشي بالشرح بطيء وبيسألكم تبون نمشي على هالوتيره ولا نزيد السرعه\nاحيانا راح يعطي كلاسات زياده لـ واحد من 3 اسباب\n1- متأخرين بالمنهج\n2- بطلب من الطلاب او لمصلحتهم اذا يبون\n3- بحكم عمله في مشروع يسر , احيانا يسافر في رحلات عمل ويكنسل كلاسات ويعوضها\n\nالكورس ممتع مع الدكتور , واذا ما فهمت الديتابيس معاه فما راح تفهمها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1057689-mis311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saad-al-ahmadi/98435/5", "user": "S.a.l.m.a.n", "ts": 1340178773000, "tid": 98435, "pn": 5}}]}', 1340178773000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-mis311', 'stk-sadguts', 'MIS 311', 'doc', '{"docs": [{"id": "stk-dr-f180467", "n": "Dr. Jongtae Yu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS311 - 212\nالدكتور رهيب وشرحه ممتاز يوصل المعلومة بوضوح وماعنده مشكلة يعيد النقطة اكثر من مرة. اكثر دكتور اخلاقه حلوة وحبييييب\n\nكويزاته سهلة - متوسطة والهوموركات اصعب شوي لكن مقدور عليها\n\nالميدتيرم كان جزء خيارات وجزء ترسم erd وماكان صعب وتصحيح الدكتور اسطوري اصلا\nوالفاينل كان كله رتن ترسم erd وتسوي نورملايزيشن لداتا بيس وتكتب اكواد sql\n\nالكورس بشكل عام مو صعب لكن لازم تعطيه حقه ك طالب mis لانه مهم جدا للتخصص خصوصا لو حاب database design", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534678-mis311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jongtae-yu/180467/6", "user": "SadGuts", "ts": 1655718790000, "tid": 180467, "pn": 6}}]}', 1655718790000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12263-mis311', 'stk-user12263', 'MIS 311', 'doc', '{"docs": [{"id": "stk-dr-f180467", "n": "Dr. Jongtae Yu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده في فصل 212 مادة MIS 311.\n\nالتحضير : ما كان يحضر.\nطريقة الشرح : يشرح الكونسبت عن طريق السلايدات وعلى السبورة ويعطي أمثلة عليها، ويتقبل الأسئلة بصدر رحب.\nالكويزات : كانت سهلة، وعلى كلام الطلاب انه كان يجيب من ال TB، بس انا ما كنت أطلع عليه. بالإضافة أنه زاد كويز وحذف أسوء واحد.\nالمياجر: كان فيه اختبار نصفي عبارة عن اختيارات، وصح وخطأ، وكتابي يطلب منك ترسم ERD.\nالفاينلات : كان كله كتابي عبارة عن SQL, ERD, Normalization وماكان صعب.\nالقريد النهائي: ممتاز جدًا مرتفع مع مرتبة الشرف الأولى المتميزة الخارقة (A+).\nالصوت: واضح بس اللهجة لك عليها يعني يبيلك أسبوعين وتمسك معه (Any kitchens = Any questions).\nإضافات : الدكتور متساعد في المحاضرات، والساعات المكتبية، وحتى يعطيك من وقته الخاص في مايكروسوفت تيمز. الدكتور تصحيحه ممتاز في الواجبات، والاختبارات والمشروع وراح يعطيكم حلويات مع التصحيح لكن لاتفكر أنه يعطيك حلويات في التقدير النهائي. أيضًا ساعدنا في المشروع وكان يدعمنا ويعطينا استشارات ويشرح على العموم من وجهة نظري أشوف أنه من أفضل الدكاترة الموجودين.\n\nطلعت من عنده ب A.\nينقصه أنه يدخل الاسلام ويصير أفضل دكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535888-mis311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jongtae-yu/180467/7", "user": "user12263", "ts": 1668234348000, "tid": 180467, "pn": 7}}]}', 1668234348000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
